{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configuration, which could allow unintended public access to the bucket."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, which makes it difficult to track access requests and detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket does not explicitly block public ACLs, which could allow public access if ACLs are misconfigured."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
  }, {})

  logging {
    target_bucket = "${local.resource_prefix.value}-log-bucket"
    target_prefix = "${local.resource_prefix.value}/"
  }

  lifecycle_rule {
    enabled = true
    expiration {
      days = 365
    }
  }
}

resource "aws_s3_bucket_public_access_block" "flowbucket_block" {
  bucket                  = aws_s3_bucket.flowbucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Added a Public Access block to prevent public access, enabled access logging to track access requests, and blocked public ACLs to mitigate potential misconfigurations."
}
